import React, { useState } from "react";
import './Navigation.css';
import logo from '../../assets/shared/logo.svg';
import cross from '../../assets/shared/icon-close.svg';
import { Link } from 'react-router-dom';
import { spaceAudio } from '../../utils/SpaceAudio';

export default function NavBar({ activeClass = ["", "", "", "", ""] }) {
    const [isOpen, setIsOpen] = useState(false);
    const [style, setStyle] = useState({});
    const [isAudioPlaying, setIsAudioPlaying] = useState(false);

    function hamburgerMenu() {
        if (!isOpen) {
            setIsOpen(true);
            setStyle({ transform: 'translate(0%)' });
        } else {
            setIsOpen(false);
            setStyle({ transform: 'translate(100%)' });
        }
    }

    const handleAudioToggle = () => {
        const state = spaceAudio.toggleAmbientSound();
        setIsAudioPlaying(state);
    };

    const handleNavClick = () => {
        spaceAudio.playClickSound();
    };

    return (
        <div className="NavBar flex">
            <Link to="/SpaceTourism/" onClick={handleNavClick}>
                <img src={logo} alt="Space tourism logo" className="logo-img"></img>
            </Link>
            <div className="nav-line"></div>

            <button 
                className={`audio-toggle-btn ${isAudioPlaying ? 'playing' : ''}`}
                onClick={handleAudioToggle}
                title={isAudioPlaying ? "Mute Ambient Cosmic Sound" : "Play Ambient Cosmic Sound"}
                aria-label="Toggle Cosmic Soundscape"
            >
                <span className="sound-icon">📡</span>
                <span className="sound-text ff-san-cond fs-200 uppercase">
                    {isAudioPlaying ? "Cosmic Radio ON" : "Cosmic Radio OFF"}
                </span>
                {isAudioPlaying && (
                    <span className="sound-wave">
                        <span></span><span></span><span></span>
                    </span>
                )}
            </button>

            <button 
                className="Navbar-toggle" 
                style={isOpen ? { backgroundImage: `url(${cross})` } : {}} 
                onClick={hamburgerMenu}
            >
                <span className="sr-only">Menu</span>
            </button>

            <nav>
                <ul style={style} className="primary-navigation linear-indicators flex fs-300 letter-spacing-2 ff-san-cond text-white upperCase">
                    <li className={activeClass[0]} onClick={handleNavClick}>
                        <Link to="/SpaceTourism/"><span>00</span>Home</Link>
                    </li>
                    <li className={activeClass[1]} onClick={handleNavClick}>
                        <Link to="/SpaceTourism/destination"><span>01</span>Destination</Link>
                    </li>
                    <li className={activeClass[2]} onClick={handleNavClick}>
                        <Link to="/SpaceTourism/crew"><span>02</span>Crew</Link>
                    </li>
                    <li className={activeClass[3]} onClick={handleNavClick}>
                        <Link to="/SpaceTourism/technology"><span>03</span>Technology</Link>
                    </li>
                    <li className={activeClass[4]} onClick={handleNavClick}>
                        <Link to="/SpaceTourism/book"><span>04</span>Book</Link>
                    </li>
                </ul>
            </nav>
        </div>
    );
}
